dataSet.query:
ВЫБРАТЬ РАЗЛИЧНЫЕ РазделыОтчета.Раздел КАК РазделОтчета, ЕСТЬNULL(ТаблицыОтчета.Таблица, "") КАК Таблица ПОМЕСТИТЬ СтруктураОтчета {ВЫБРАТЬ РазделОтчета, Таблица} ИЗ (ВЫБРАТЬ "1" КАК Раздел
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ "2"
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ "3") КАК РазделыОтчета ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ "Дт" КАК Таблица
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ "Кт") КАК ТаблицыОтчета ПО (РазделыОтчета.Раздел = "2") {ГДЕ РазделыОтчета.Раздел КАК РазделОтчета, (ЕСТЬNULL(ТаблицыОтчета.Таблица, "")) КАК Таблица} ;
